    "grammar-flashcards": {
      "title": "Lesson 16 Grammar Flashcards",
      "cards": [
        {
          "prompt": "Why are πατρός and πατέρα different stems?",
          "answer": "The family-noun pattern drops ε in genitive/dative singular but retains it in accusative."
        },
        {
          "prompt": "What is the gender of χείρ?",
          "answer": "Feminine: ἡ χείρ."
        },
        {
          "prompt": "How does πᾶσα ἡ στρατιά differ from πᾶς στρατιώτης?",
          "answer": "The whole army as a unit versus every soldier individually."
        },
        {
          "prompt": "Does πέντε change to agree with feminine ἡμέρας?",
          "answer": "No. πέντε is indeclinable, though ἡμέρας still has case."
        },
        {
          "prompt": "What question does τρεῖς ἡμέρας answer after μένει?",
          "answer": "How long does he stay? Three days."
        }
      ]
    },
